insert into public.word_examples (word_id, order_index, sentence_en, sentence_vi) values
('10000001-0000-4000-8000-000000000001', 1, 'Close the door, please.', 'Làm ơn đóng cửa lại.'),
('10000001-0000-4000-8000-000000000001', 2, 'The book on the table is mine.', 'Cuốn sách trên bàn là của tôi.'),
('10000001-0000-4000-8000-000000000001', 3, 'She is the tallest in her class.', 'Cô ấy cao nhất lớp.'),
('10000002-0000-4000-8000-000000000002', 1, 'I want to be a doctor.', 'Tôi muốn trở thành bác sĩ.'),
('10000002-0000-4000-8000-000000000002', 2, 'Will you be at home tonight?', 'Tối nay bạn có ở nhà không?'),
('10000002-0000-4000-8000-000000000002', 3, 'Try to be on time.', 'Cố gắng đúng giờ nhé.'),
('10000003-0000-4000-8000-000000000003', 1, 'I go to school by bus.', 'Tôi đến trường bằng xe buýt.'),
('10000003-0000-4000-8000-000000000003', 2, 'She wants to learn English.', 'Cô ấy muốn học tiếng Anh.'),
('10000003-0000-4000-8000-000000000003', 3, 'Give this to your mother.', 'Đưa cái này cho mẹ bạn.'),
('10000004-0000-4000-8000-000000000004', 1, 'This is a photo of my family.', 'Đây là ảnh gia đình tôi.'),
('10000004-0000-4000-8000-000000000004', 2, 'He drank a cup of tea.', 'Anh ấy uống một tách trà.'),
('10000004-0000-4000-8000-000000000004', 3, 'The end of the film was sad.', 'Đoạn kết của bộ phim thật buồn.'),
('10000005-0000-4000-8000-000000000005', 1, 'I like tea and coffee.', 'Tôi thích trà và cà phê.'),
('10000005-0000-4000-8000-000000000005', 2, 'She sat down and opened her book.', 'Cô ấy ngồi xuống và mở sách.'),
('10000005-0000-4000-8000-000000000005', 3, 'It is cheap and very good.', 'Nó rẻ và rất tốt.'),
('10000006-0000-4000-8000-000000000006', 1, 'I have a question.', 'Tôi có một câu hỏi.'),
('10000006-0000-4000-8000-000000000006', 2, 'She bought a new phone.', 'Cô ấy mua một chiếc điện thoại mới.'),
('10000006-0000-4000-8000-000000000006', 3, 'There is a cat in the garden.', 'Có một con mèo trong vườn.'),
('10000007-0000-4000-8000-000000000007', 1, 'The keys are in my bag.', 'Chìa khoá ở trong túi tôi.'),
('10000007-0000-4000-8000-000000000007', 2, 'She lives in Hanoi.', 'Cô ấy sống ở Hà Nội.'),
('10000007-0000-4000-8000-000000000007', 3, 'We will meet in an hour.', 'Chúng ta sẽ gặp nhau sau một tiếng.'),
('10000008-0000-4000-8000-000000000008', 1, 'That house is very old.', 'Ngôi nhà đó rất cũ.'),
('10000008-0000-4000-8000-000000000008', 2, 'I know that you are busy.', 'Tôi biết rằng bạn đang bận.'),
('10000008-0000-4000-8000-000000000008', 3, 'Who told you that?', 'Ai nói với bạn điều đó?'),
('10000009-0000-4000-8000-000000000009', 1, 'I have two brothers.', 'Tôi có hai anh em trai.'),
('10000009-0000-4000-8000-000000000009', 2, 'Do you have a pen?', 'Bạn có bút không?'),
('10000009-0000-4000-8000-000000000009', 3, 'We have a meeting today.', 'Hôm nay chúng tôi có cuộc họp.'),
('10000010-0000-4000-8000-000000000010', 1, 'I am a student.', 'Tôi là sinh viên.'),
('10000010-0000-4000-8000-000000000010', 2, 'I do not understand.', 'Tôi không hiểu.'),
('10000010-0000-4000-8000-000000000010', 3, 'Can I ask you something?', 'Tôi hỏi bạn một chút được không?'),
('10000011-0000-4000-8000-000000000011', 1, 'It is raining outside.', 'Trời đang mưa bên ngoài.'),
('10000011-0000-4000-8000-000000000011', 2, 'I like it very much.', 'Tôi rất thích nó.'),
('10000011-0000-4000-8000-000000000011', 3, 'It takes about ten minutes.', 'Nó mất khoảng mười phút.'),
('10000012-0000-4000-8000-000000000012', 1, 'This gift is for you.', 'Món quà này dành cho bạn.'),
('10000012-0000-4000-8000-000000000012', 2, 'She waited for an hour.', 'Cô ấy đợi một tiếng.'),
('10000012-0000-4000-8000-000000000012', 3, 'Thank you for your help.', 'Cảm ơn bạn đã giúp đỡ.'),
('10000013-0000-4000-8000-000000000013', 1, 'I am not hungry.', 'Tôi không đói.'),
('10000013-0000-4000-8000-000000000013', 2, 'She does not like coffee.', 'Cô ấy không thích cà phê.'),
('10000013-0000-4000-8000-000000000013', 3, 'It is not far from here.', 'Nó không xa đây.'),
('10000014-0000-4000-8000-000000000014', 1, 'The book is on the table.', 'Cuốn sách ở trên bàn.'),
('10000014-0000-4000-8000-000000000014', 2, 'We meet on Monday.', 'Chúng tôi gặp nhau vào thứ Hai.'),
('10000014-0000-4000-8000-000000000014', 3, 'Put your bag on the chair.', 'Để túi của bạn lên ghế.'),
('10000015-0000-4000-8000-000000000015', 1, 'I live with my parents.', 'Tôi sống với bố mẹ.'),
('10000015-0000-4000-8000-000000000015', 2, 'She went with her friends.', 'Cô ấy đi cùng bạn bè.'),
('10000015-0000-4000-8000-000000000015', 3, 'Cut it with a knife.', 'Cắt nó bằng dao.'),
('10000016-0000-4000-8000-000000000016', 1, 'He is my brother.', 'Anh ấy là anh trai tôi.'),
('10000016-0000-4000-8000-000000000016', 2, 'He works at a bank.', 'Anh ấy làm ở ngân hàng.'),
('10000016-0000-4000-8000-000000000016', 3, 'Does he speak English?', 'Anh ấy có nói tiếng Anh không?'),
('10000017-0000-4000-8000-000000000017', 1, 'She works as a teacher.', 'Cô ấy làm giáo viên.'),
('10000017-0000-4000-8000-000000000017', 2, 'He is as tall as his father.', 'Cậu ấy cao bằng bố.'),
('10000017-0000-4000-8000-000000000017', 3, 'Do as I say.', 'Hãy làm như tôi nói.'),
('10000018-0000-4000-8000-000000000018', 1, 'You are very kind.', 'Bạn thật tốt bụng.'),
('10000018-0000-4000-8000-000000000018', 2, 'Where do you live?', 'Bạn sống ở đâu?'),
('10000018-0000-4000-8000-000000000018', 3, 'I will call you tomorrow.', 'Mai tôi sẽ gọi cho bạn.'),
('10000019-0000-4000-8000-000000000019', 1, 'What do you do every morning?', 'Mỗi sáng bạn làm gì?'),
('10000019-0000-4000-8000-000000000019', 2, 'I do my homework after dinner.', 'Tôi làm bài tập sau bữa tối.'),
('10000019-0000-4000-8000-000000000019', 3, 'Do it carefully.', 'Hãy làm cẩn thận.'),
('10000020-0000-4000-8000-000000000020', 1, 'We meet at the station.', 'Chúng tôi gặp nhau ở nhà ga.'),
('10000020-0000-4000-8000-000000000020', 2, 'The class starts at eight.', 'Lớp học bắt đầu lúc tám giờ.'),
('10000020-0000-4000-8000-000000000020', 3, 'She is at home now.', 'Bây giờ cô ấy đang ở nhà.'),
('10000021-0000-4000-8000-000000000021', 1, 'This is my house.', 'Đây là nhà tôi.'),
('10000021-0000-4000-8000-000000000021', 2, 'I like this song.', 'Tôi thích bài hát này.'),
('10000021-0000-4000-8000-000000000021', 3, 'This week is very busy.', 'Tuần này rất bận.'),
('10000022-0000-4000-8000-000000000022', 1, 'It is small but comfortable.', 'Nó nhỏ nhưng thoải mái.'),
('10000022-0000-4000-8000-000000000022', 2, 'I called her but she did not answer.', 'Tôi gọi cô ấy nhưng cô ấy không nghe máy.'),
('10000022-0000-4000-8000-000000000022', 3, 'He is tired but happy.', 'Anh ấy mệt nhưng vui.'),
('10000023-0000-4000-8000-000000000023', 1, 'This is his car.', 'Đây là xe của anh ấy.'),
('10000023-0000-4000-8000-000000000023', 2, 'His name is Nam.', 'Tên anh ấy là Nam.'),
('10000023-0000-4000-8000-000000000023', 3, 'He forgot his keys again.', 'Anh ấy lại quên chìa khoá.'),
('10000024-0000-4000-8000-000000000024', 1, 'I go to work by bus.', 'Tôi đi làm bằng xe buýt.'),
('10000024-0000-4000-8000-000000000024', 2, 'The house by the river is new.', 'Ngôi nhà cạnh sông thì mới.'),
('10000024-0000-4000-8000-000000000024', 3, 'Finish it by Friday.', 'Hoàn thành trước thứ Sáu.'),
('10000025-0000-4000-8000-000000000025', 1, 'I am from Vietnam.', 'Tôi đến từ Việt Nam.'),
('10000025-0000-4000-8000-000000000025', 2, 'She walked home from school.', 'Cô ấy đi bộ từ trường về nhà.'),
('10000025-0000-4000-8000-000000000025', 3, 'The shop is open from nine.', 'Cửa hàng mở từ chín giờ.'),
('10000026-0000-4000-8000-000000000026', 1, 'They are my neighbors.', 'Họ là hàng xóm của tôi.'),
('10000026-0000-4000-8000-000000000026', 2, 'They live in the city.', 'Họ sống ở thành phố.'),
('10000026-0000-4000-8000-000000000026', 3, 'Do they know about it?', 'Họ có biết về chuyện đó không?'),
('10000027-0000-4000-8000-000000000027', 1, 'We are ready.', 'Chúng tôi đã sẵn sàng.'),
('10000027-0000-4000-8000-000000000027', 2, 'We eat dinner at seven.', 'Chúng tôi ăn tối lúc bảy giờ.'),
('10000027-0000-4000-8000-000000000027', 3, 'Shall we go now?', 'Chúng ta đi bây giờ nhé?'),
('10000028-0000-4000-8000-000000000028', 1, 'What did you say?', 'Bạn vừa nói gì?'),
('10000028-0000-4000-8000-000000000028', 2, 'Say it again, please.', 'Xin hãy nói lại.'),
('10000028-0000-4000-8000-000000000028', 3, 'I want to say thank you.', 'Tôi muốn nói lời cảm ơn.'),
('10000029-0000-4000-8000-000000000029', 1, 'I saw her yesterday.', 'Hôm qua tôi gặp cô ấy.'),
('10000029-0000-4000-8000-000000000029', 2, 'Her bag is on the chair.', 'Túi của cô ấy ở trên ghế.'),
('10000029-0000-4000-8000-000000000029', 3, 'Give the book to her.', 'Đưa cuốn sách cho cô ấy.'),
('10000030-0000-4000-8000-000000000030', 1, 'She is a nurse.', 'Cô ấy là y tá.'),
('10000030-0000-4000-8000-000000000030', 2, 'She lives near the school.', 'Cô ấy sống gần trường.'),
('10000030-0000-4000-8000-000000000030', 3, 'Does she like music?', 'Cô ấy có thích âm nhạc không?'),
('10000031-0000-4000-8000-000000000031', 1, 'Tea or coffee?', 'Trà hay cà phê?'),
('10000031-0000-4000-8000-000000000031', 2, 'We can walk or take a taxi.', 'Chúng ta có thể đi bộ hoặc bắt taxi.'),
('10000031-0000-4000-8000-000000000031', 3, 'Hurry up or you will be late.', 'Nhanh lên không thì bạn muộn mất.'),
('10000032-0000-4000-8000-000000000032', 1, 'I ate an apple.', 'Tôi đã ăn một quả táo.'),
('10000032-0000-4000-8000-000000000032', 2, 'She is an engineer.', 'Cô ấy là kỹ sư.'),
('10000032-0000-4000-8000-000000000032', 3, 'Wait an hour, please.', 'Vui lòng đợi một tiếng.'),
('10000033-0000-4000-8000-000000000033', 1, 'I will call you later.', 'Tôi sẽ gọi bạn sau.'),
('10000033-0000-4000-8000-000000000033', 2, 'She will be here soon.', 'Cô ấy sẽ tới đây sớm thôi.'),
('10000033-0000-4000-8000-000000000033', 3, 'It will rain tonight.', 'Tối nay trời sẽ mưa.'),
('10000034-0000-4000-8000-000000000034', 1, 'This is my house.', 'Đây là nhà của tôi.'),
('10000034-0000-4000-8000-000000000034', 2, 'My father is a teacher.', 'Bố tôi là giáo viên.'),
('10000034-0000-4000-8000-000000000034', 3, 'I lost my phone.', 'Tôi làm mất điện thoại.'),
('10000035-0000-4000-8000-000000000035', 1, 'I have one sister.', 'Tôi có một chị gái.'),
('10000035-0000-4000-8000-000000000035', 2, 'Only one person came.', 'Chỉ có một người đến.'),
('10000035-0000-4000-8000-000000000035', 3, 'This one is better.', 'Cái này tốt hơn.'),
('10000036-0000-4000-8000-000000000036', 1, 'All the students passed.', 'Tất cả học sinh đều đỗ.'),
('10000036-0000-4000-8000-000000000036', 2, 'She worked all day.', 'Cô ấy làm việc cả ngày.'),
('10000036-0000-4000-8000-000000000036', 3, 'That is all I know.', 'Đó là tất cả những gì tôi biết.'),
('10000037-0000-4000-8000-000000000037', 1, 'I would like some water.', 'Tôi muốn một chút nước.'),
('10000037-0000-4000-8000-000000000037', 2, 'Would you help me?', 'Bạn giúp tôi được không?'),
('10000037-0000-4000-8000-000000000037', 3, 'She said she would come.', 'Cô ấy nói cô ấy sẽ đến.'),
('10000038-0000-4000-8000-000000000038', 1, 'There is a shop near here.', 'Có một cửa hàng gần đây.'),
('10000038-0000-4000-8000-000000000038', 2, 'Put the box over there.', 'Đặt cái hộp ở đằng kia.'),
('10000038-0000-4000-8000-000000000038', 3, 'There are five people waiting.', 'Có năm người đang đợi.'),
('10000039-0000-4000-8000-000000000039', 1, 'Their house is very big.', 'Nhà của họ rất to.'),
('10000039-0000-4000-8000-000000000039', 2, 'The children took their bags.', 'Bọn trẻ lấy cặp của chúng.'),
('10000039-0000-4000-8000-000000000039', 3, 'Their son studies abroad.', 'Con trai họ du học nước ngoài.'),
('10000040-0000-4000-8000-000000000040', 1, 'What is your name?', 'Bạn tên gì?'),
('10000040-0000-4000-8000-000000000040', 2, 'What time is it?', 'Mấy giờ rồi?'),
('10000040-0000-4000-8000-000000000040', 3, 'I do not know what to say.', 'Tôi không biết nói gì.'),
('10000041-0000-4000-8000-000000000041', 1, 'It was late, so we went home.', 'Muộn rồi nên chúng tôi về nhà.'),
('10000041-0000-4000-8000-000000000041', 2, 'She is so kind.', 'Cô ấy thật tốt bụng.'),
('10000041-0000-4000-8000-000000000041', 3, 'I was tired, so I slept early.', 'Tôi mệt nên đi ngủ sớm.'),
('10000042-0000-4000-8000-000000000042', 1, 'Please stand up.', 'Xin mời đứng lên.'),
('10000042-0000-4000-8000-000000000042', 2, 'Prices went up again.', 'Giá lại tăng lên.'),
('10000042-0000-4000-8000-000000000042', 3, 'Look up at the sky.', 'Nhìn lên bầu trời kìa.'),
('10000043-0000-4000-8000-000000000043', 1, 'Let us go out tonight.', 'Tối nay chúng ta ra ngoài đi.'),
('10000043-0000-4000-8000-000000000043', 2, 'She took out her wallet.', 'Cô ấy lấy ví ra.'),
('10000043-0000-4000-8000-000000000043', 3, 'The fire went out.', 'Ngọn lửa đã tắt.'),
('10000044-0000-4000-8000-000000000044', 1, 'Call me if you need help.', 'Gọi tôi nếu bạn cần giúp.'),
('10000044-0000-4000-8000-000000000044', 2, 'If it rains, we will stay home.', 'Nếu trời mưa, chúng ta sẽ ở nhà.'),
('10000044-0000-4000-8000-000000000044', 3, 'Ask him if he is free.', 'Hỏi anh ấy xem có rảnh không.'),
('10000045-0000-4000-8000-000000000045', 1, 'We talked about the film.', 'Chúng tôi nói về bộ phim.'),
('10000045-0000-4000-8000-000000000045', 2, 'It costs about fifty thousand dong.', 'Nó giá khoảng năm mươi nghìn đồng.'),
('10000045-0000-4000-8000-000000000045', 3, 'Tell me about your family.', 'Kể tôi nghe về gia đình bạn.'),
('10000046-0000-4000-8000-000000000046', 1, 'Who is that man?', 'Người đàn ông đó là ai?'),
('10000046-0000-4000-8000-000000000046', 2, 'Who wants some tea?', 'Ai muốn uống trà nào?'),
('10000046-0000-4000-8000-000000000046', 3, 'The man who called is my uncle.', 'Người đàn ông vừa gọi là chú tôi.'),
('10000047-0000-4000-8000-000000000047', 1, 'I get up at six.', 'Tôi dậy lúc sáu giờ.'),
('10000047-0000-4000-8000-000000000047', 2, 'She will get a new job.', 'Cô ấy sẽ nhận được công việc mới.'),
('10000047-0000-4000-8000-000000000047', 3, 'It gets cold at night.', 'Về đêm trời trở lạnh.'),
('10000048-0000-4000-8000-000000000048', 1, 'Which one do you want?', 'Bạn muốn cái nào?'),
('10000048-0000-4000-8000-000000000048', 2, 'Which bus goes downtown?', 'Xe buýt nào đi vào trung tâm?'),
('10000048-0000-4000-8000-000000000048', 3, 'The book which I read was long.', 'Cuốn sách mà tôi đọc thì dài.'),
('10000049-0000-4000-8000-000000000049', 1, 'I go to work by bike.', 'Tôi đi làm bằng xe đạp.'),
('10000049-0000-4000-8000-000000000049', 2, 'Let us go home now.', 'Chúng ta về nhà thôi.'),
('10000049-0000-4000-8000-000000000049', 3, 'Where does this road go?', 'Con đường này đi đâu?'),
('10000050-0000-4000-8000-000000000050', 1, 'Please help me.', 'Làm ơn giúp tôi.'),
('10000050-0000-4000-8000-000000000050', 2, 'She gave me a book.', 'Cô ấy tặng tôi một cuốn sách.'),
('10000050-0000-4000-8000-000000000050', 3, 'Call me tonight.', 'Gọi cho tôi tối nay.'),
('10000051-0000-4000-8000-000000000051', 1, 'When does the class start?', 'Lớp học bắt đầu khi nào?'),
('10000051-0000-4000-8000-000000000051', 2, 'Call me when you arrive.', 'Gọi tôi khi bạn tới nơi.'),
