-- ============================================================================
-- KHOA '1000 TU VUNG CO BAN' = 1000 tu tieng Anh thong dung nhat
-- Xep theo tan suat, chia 20 nhom x 50 tu. Moi tu 3 cau vi du co dich.
-- Khoa nay DOC LAP voi khoa 'Tu vung theo chu de' — trung tu la binh thuong.
-- Chay thang file nay la du. An toan chay lai nhieu lan.
-- ============================================================================

-- Bang cau vi du (tao neu chua co)
create table if not exists public.word_examples (
  word_id     uuid not null references public.words(id) on delete cascade,
  order_index int  not null,
  sentence_en text not null,
  sentence_vi text,
  primary key (word_id, order_index)
);
alter table public.word_examples enable row level security;
drop policy if exists "word_examples_read" on public.word_examples;
create policy "word_examples_read" on public.word_examples
  for select to authenticated using (exists (
    select 1 from public.words w
    join public.topics t  on t.id = w.topic_id
    join public.courses c on c.id = t.course_id
    where w.id = word_id and c.is_published));

-- ⚠️ XOA 3 chu de mau ban dau cua khoa nay (Family & Friends, Food & Drinks,
--    Travel — tong 24 tu demo) de thay bang cac nhom theo tan suat.
--    Tien do hoc cua 24 tu do (neu co) se mat theo. Cac khoa khac khong bi anh huong.
delete from public.topics
 where course_id = 'c1111111-1111-4111-8111-111111111111'
   and id::text not like 'e2000000-%';

-- 1. NHOM TU (dong vai tro 'chu de')
on conflict (id) do nothing;

-- 2. TU VUNG
on conflict (id) do nothing;

-- 3. CAU VI DU + BAN DICH
on conflict (word_id, order_index) do nothing;

-- 4. Cap nhat mo ta khoa hoc
update public.courses set total_words = 1000,
       description = '1000 từ xuất hiện nhiều nhất trong tiếng Anh, xếp theo tần suất'
where id = 'c1111111-1111-4111-8111-111111111111';
